revoke all on group_members from anon, authenticated;
alter table group_invites enable row level security;
revoke all on group_invites from anon, authenticated;
alter table posts enable row level security;
revoke all on posts from anon, authenticated;
alter table comments enable row level security;
revoke all on comments from anon, authenticated;
alter table events enable row level security;
revoke all on events from anon, authenticated;
alter table event_attendees enable row level security;
revoke all on event_attendees from anon, authenticated;
alter table documents enable row level security;
revoke all on documents from anon, authenticated;
alter table document_chunks enable row level security;
revoke all on document_chunks from anon, authenticated;
alter table chat_sessions enable row level security;
revoke all on chat_sessions from anon, authenticated;
alter table chat_messages enable row level security;
revoke all on chat_messages from anon, authenticated;
alter table audit_logs enable row level security;
revoke all on audit_logs from anon, authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values ('group-documents','group-documents',false,20971520,array['application/pdf']) on conflict(id) do update set public=false,file_size_limit=20971520,allowed_mime_types=array['application/pdf'];
